  let cur = '';
  for (let i = 0; i < listStr.length; i++) {
    if (listStr[i] === ',') { if (cur.length) items.push(Number(cur)); cur = ''; }
    else cur += listStr[i];
  }
  if (cur.length) items.push(Number(cur));
  return {items, next};
}
