  return await host.readAsync(key)
    .then(function(v) {
      host.store('ok:' + key, v * 2);
      return v * 2;
    }, function(err) {
      host.store('err:' + key, err);
      return fallback;
    })
    .finally(function() {
      host.store('done:' + key, 1);
    });
}

